var t=`0577-ashlyan-fu`;var n=`world-0577`;var a=`KG`;var o=`central-asia`;var r=4;var s=99;var l={en:`Ashlyan-Fu`,ua:`Ашлян-фу`};var g={en:`A traditional dish from Kyrgyzstan, centered on rice noodles, potato starch, light soy sauce, white vinegar. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Киргизстан. Основні складники: рисова локшина, картопляний крохмаль, світлий соєвий соус, білий оцет. Домашній варіант із кількостями продуктів за етапами приготування.`};var h=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`rice-noodles`,280,`g`],[`water`,1200,`ml`]]},{en:`Dissolve potato starch in cold water with vinegar and soy sauce, then heat while stirring into a glossy firm jelly; cool and slice into ribbons.`,ua:`Розчиніть картопляний крохмаль у холодній воді з оцтом і соєвим соусом, нагрівайте до густого прозорого киселю; остудіть і наріжте смужками.`,t:[`gelatinizing-starch`],m:9,i:[[`potato-starch`,65,`g`],[`light-soy-sauce`,55,`ml`],[`white-vinegar`,60,`ml`],[`hot-paprika`,5,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`sunflower-oil`,55,`ml`]]},{en:`Cool the prepared ingredients promptly, then refrigerate for about 70 minutes until properly chilled.`,ua:`Швидко охолодіть підготовлені складники, потім поставте в холодильник приблизно на 70 хвилин.`,t:[`rapid-chilling`],m:70,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cucumber`,260,`g`],[`cilantro`,25,`g`]]}];var d={slug:t,id:n,country:`KG`,region:o,servings:4,minutes:99,title:l,text:g,steps:h};export{a as country,d as default,n as id,s as minutes,o as region,r as servings,t as slug,h as steps,g as text,l as title};